INSERT INTO `about_content` (`id`, `content`, `fleet_icon`, `fleet_name`, `fleet_content`, `network_icon`, `network_name`, `network_content`, `delivery_icon`, `delivery_name`, `delivery_content`, `states_covered`, `branches`, `daily_shipments`, `years_experience`, `created_at`, `updated_at`) VALUES
(1, '<div class=\"aboutoneSec\">\r\n<div class=\"presencehding txtcenter\">\r\n<h2>Who We Are&nbsp;</h2>\r\n\r\n<p>SPS Paarcel Private Limited is a leading freight forwarding and logistics company providing transportation and freight forwarding services across India.</p>\r\n\r\n<p>Our organization operates its own fleet of trucks and offers reliable logistics services in thee. regions of Andhra Pradesh, Assam, Bihar, Chhattisgarh, Delhi, Gujarat, Haryana, Jharkhand, Madhya Pradesh, Maharasthara, Odisha, Punjab, Rajasthan, Tamil Nadu, Uttar Pradesh and West Bengal.</p>\r\n</div>\r\n\r\n<div class=\"abutepnel\">\r\n<div class=\"media\">\r\n<div class=\"abutemeimge\"><img alt=\"\" src=\"https://paarcel3u.in/admin/assets/admin/images/image43.png\" style=\"width:450px\" /></div>\r\n\r\n<div class=\"media-object\">\r\n<p>Since its inception, PAARCEL has been committed to delivering full-truck load and parcel services through a strong fleet network and trained support staff.!</p>\r\n&nbsp;\r\n\r\n<p>&nbsp;</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 'uploads/aboutus/fleet_1775645285_503.png', 'Own Fleet', 'We operate our own trucks for reliable transport.', 'uploads/aboutus/network_1775645195_831.png', 'Nationwide Network', 'Operating across major industrial states in India.', 'uploads/aboutus/delivery_1775645257_778.png', 'Reliable Delivery', 'Full-truck load and parcel services for businesses.', '15', '120', '500', '10', '2026-04-07 10:21:44', '2026-07-22 06:34:22');
