(2, 1, 'Track Your Shipment', 'Track Your Shipment', 'Enter the LR/ Consignment number from your receipt', 'uploads/services/service-1778760154.png', 1, NULL, 1, '2026-02-06 09:05:00', '2026-05-14 06:37:39'),
(3, 2, 'Footer Banner', 'footer banner', 'footer banner', 'uploads/services/service-1771914103.jpg', 1, NULL, 1, '2026-02-24 00:51:43', NULL),
(4, 3, 'Our Services', 'Services', 'Services', 'uploads/services/service-1772181585.jpg', 1, NULL, 1, '2026-02-27 03:09:45', NULL),
(5, 4, 'Networks', 'Networks', 'Our transport network extends across several key regions of India, including Andhra Pradesh, Assam, Bihar, Chhattisgarh, Delhi, Gujarat, Haryana, Jharkhand, Madhya Pradesh, Maharashtra, Odisha, Punjab, Rajasthan, Tamil Nadu, Uttar Pradesh, and West Bengal. This widespread presence enables us to efficiently connect major industrial, commercial, and emerging markets across the country. Through a well-coordinated logistics system supported by experienced personnel and dependable infrastructure, we ensure the smooth, safe, and timely movement of goods. Our strong regional connectivity allows us to deliver consistent, reliable transport solutions while meeting the diverse logistics needs of businesses across these states.', 'uploads/services/service-1772264039.jpg', 1, NULL, 1, '2026-02-28 02:03:59', '2026-03-12 02:03:18'),
(6, 5, 'Tracking', 'Tracking', 'Tracking', 'uploads/services/service-1772435764.jpg', 1, NULL, 1, '2026-03-02 01:46:04', '2026-03-09 23:51:27'),
(8, 6, 'About Us', 'About Us', NULL, 'uploads/services/service-1773215369.webp', 1, NULL, 1, '2026-03-11 00:58:23', '2026-03-11 02:19:29'),
(9, 7, 'Career', 'Career', NULL, 'uploads/services/service-1773215347.webp', 1, NULL, 1, '2026-03-11 01:00:25', '2026-03-11 02:19:07'),
(10, 8, 'Location', 'Location', 'Connecting Major Commercial & Industrial Regions Across India Our transport network spans key industrial regions across India including Andhra Pradesh, Assam, Bihar, Chhattisgarh, Delhi, Gujarat, Haryana, Jharkhand, Madhya Pradesh, Maharashtra, Odisha, Punjab, Rajasthan, Tamil Nadu, Uttar Pradesh and West Bengal.', 'uploads/services/service-1776497814.svg', 1, NULL, 1, '2026-04-02 01:41:44', '2026-06-15 01:45:16'),
(11, 9, 'Privacy Policy', 'Privacy Policy', NULL, 'uploads/services/service-1773215369.webp', 1, NULL, 1, '2026-03-11 00:58:23', '2026-03-11 02:19:29');
