INSERT INTO `cms_email_templates` (`id`, `name`, `slug`, `subject`, `content`, `description`, `from_name`, `from_email`, `cc_email`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Forgot Password', 'forgot-password', 'Reset Password', '<p>&nbsp;</p>\r\n\r\n<p><font color=\"#222222\" face=\"Arial, Helvetica, sans-serif\" size=\"2\"><b>Hi [username], </b></font></p>\r\n\r\n<p>You are receiving this email because we received a password reset request from your account.</p>\r\n\r\n<p><a href=\"[reset_link]\">Reset Password</a></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>If you did not request a password reset, no further action is required.</p>\r\n\r\n<p>Best Regards,&nbsp;</p>\r\n\r\n<p>Print Convert&nbsp;Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[username]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-05-16 02:11:47', '2025-11-20 04:04:18'),
(2, 'Email Template Forgot Password Backend', 'forgot_password_backend', 'Forgot Password', '<p>Hi [Name],</p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">You have requested</span>&nbsp;to reset your password.&nbsp; Here is your new password:&nbsp;</p>\r\n\r\n<p>[password]</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Best Regards,</p>\r\n\r\n<p>Print Convert&nbsp;Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[password]', 'Print Convert Network', 'test.developers2020@gmail.com', NULL, 1, 1, 1, '2024-05-17 06:31:23', '2025-11-20 02:16:13'),
(3, 'New Candidate Registration', 'candidate-registration', 'Thank You For Registering as a Candidate', '<p>Thank you <span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\"><b>[name]</b> for registering with </span>Print Convert&nbsp;Network<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\"> as a Candidate. You can now log in to search for jobs that match your preferences.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Best Regards,</p>\r\n\r\n<p>Print Convert&nbsp;Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[name]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-05-17 07:08:56', '2025-11-20 04:05:09'),
(4, 'New Employer Registration', 'employer-registration', 'Thank You For Registering as an Employer', '<p>Thank you <span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\"><b>[name]</b> for registering with </span>Print Convert&nbsp;Network<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\"> as an Employer. You can now log in with your credentials. Please make sure you update you address and Company information before purchasing a Package or adding a new job listing.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Best Regards,</p>\r\n\r\n<p>Print Convert&nbsp;Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[name]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-08-21 07:08:56', '2025-11-20 04:09:17'),
(5, 'Contact a Recruiter', 'contact-recruiter', 'Thank You For Contacting a Recruiter', '<p>Dear Admin,</p>\r\n\r\n<p>Someone has requested to contact a recruiter. Please find the details below:</p>\r\n\r\n<p>Name :&nbsp;<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[name]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Email : [email]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Phone Number : [phone_number]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Message : [message]</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Regards,</p>\r\n\r\n<p>Support Team</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[name],[email],[phone_number],[message]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-08-29 13:58:56', '2026-06-15 01:44:35'),
(6, 'Communication', 'communication-user', '[subject]', '<p>Dear [name],</p>\r\n\r\n<p>[Content]</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. do not reply to this address</p>', '[name],[content]', 'PrintConvert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 16, '2024-08-29 13:58:56', '2025-11-21 18:14:36'),
(7, 'Contact Us Request Admin', 'contact-us-admin', 'Contact Us Request', '<p>Dear Admin,</p>\r\n\r\n<p>A new inquiry has been received through the <strong>&ldquo;Contact Us&rdquo;</strong> form on the website. The details of the submission are provided below:</p>\r\n\r\n<p>Name :&nbsp;<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[name]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Email : [email]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Phone Number : [phone_number]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Message : [message]</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Regards,</p>\r\n\r\n<p>Support Team</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[name],[email],[phone_number],[message]', 'Parcell', 'Paarcel@paarcel3u.in', NULL, 1, 1, 1, '2024-08-29 13:58:56', '2026-03-12 00:37:02'),
(8, 'Contact Us', 'contact-us', 'Thank You for Contacting Us', '<p>Dear [name],</p>\r\n\r\n<p>Thank you for contacting Parrcell.&nbsp; We have received your message and appreciate you reaching out to us.</p>\r\n\r\n<p>One of our team members will get back to you shortly to assist with your inquiry.&nbsp; Thank you for your patience, and we look forward to assisting you soon.</p>\r\n\r\n<p>Best regards,</p>\r\n\r\n<p>Parrcell</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto-generated email. Do not reply to this address.</p>', '[Name]', 'Parrcell', 'Paarcel@paarcel3u.in', NULL, 1, 1, 1, '2024-08-29 13:58:56', '2026-03-12 00:09:30'),
(9, 'Application Status', 'application-status', 'Your Job Application Status', '<p>Dear <span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[name]</span>,</p>\r\n\r\n<p>The status of your job application has been updated. Your current application status is:&nbsp; &nbsp; &nbsp; &nbsp;.</p>\r\n\r\n<p>Job Title:&nbsp;<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[jobtitle]</span></p>\r\n\r\n<p><span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">Status: [status]</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Best Regards,</p>\r\n\r\n<p>Print Convert Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>*This is an auto generated email. Do not reply to this address.</p>', '[name],[email],[phone_number],[message]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-08-29 13:58:56', '2025-11-20 02:18:54'),
(10, 'Job Alert', 'job_alert', 'A new Job Alert', '<p>Dear <span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[Name]</span>,</p>\r\n\r\n<p>A Job Alert for You:&nbsp; &nbsp; &nbsp; &nbsp;.</p>\r\n\r\n<p>Job Title:&nbsp;<span style=\"font-family: Calibri; font-size: 14.6667px; white-space: pre-wrap;\">[jobtitle]</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Best Regards,</p>\r\n\r\n<p>Print Convert Network</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>', '[Name],[jobtitle]', 'Print Convert Network', 'info@printconvertnetwork.com', NULL, 1, 1, 1, '2024-08-29 13:58:56', '2025-11-20 02:22:00');
